function minimumLength(s) {
  let left = 0;
  let right = s.length - 1;
  while (left < right && s[left] === s[right]) {
    const ch = s[left];
    while (left <= right && s[left] === ch) {
      left++;
    }
    while (right >= left && s[right] === ch) {
      right--;
    }
  }
  return right - left + 1;
}

