function minimumLength(s) {
  const memo = new Map();
  const shortest = (i, j) => {
    const key = i + ',' + j;
    if (memo.has(key)) return memo.get(key);
    let answer = j - i + 1;
    if (i < j && s[i] === s[j]) {
      for (let p = i; p < j && s[p] === s[i]; p++) {
        for (let q = j; q > p && s[q] === s[i]; q--) {
          answer = Math.min(answer, shortest(p + 1, q - 1));
        }
      }
    }
    memo.set(key, answer);
    return answer;
  };
  return shortest(0, s.length - 1);
}

