function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pick = () => 'abc'[int(0, 2)];
  const large = size === 'large';
  const limit = large ? 10000 : 12;
  const maxRun = large ? 40 : 3;
  for (;;) {
    let s = '';
    if (!large && rand() < 0.3) {
      const n = int(1, limit);
      for (let i = 0; i < n; i++) s += pick();
      return [s];
    }
    const centerLength = int(0, large ? 300 : 3);
    for (let i = 0; i < centerLength; i++) s += pick();
    for (;;) {
      const c = pick();
      const front = c.repeat(int(1, maxRun));
      const back = c.repeat(int(1, maxRun));
      if (s.length + front.length + back.length > limit || (!large && rand() < 0.15)) break;
      s = front + s + back;
    }
    if (large && rand() < 0.4) {
      const at = int(0, s.length - 1);
      s = s.slice(0, at) + 'abc'.replace(s[at], '')[int(0, 1)] + s.slice(at + 1);
    }
    if (s.length >= 1) return [s];
  }
}
